"""Unselected curb-entry Native alternatives and measured-trigger requirements."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent.parent
BASE = 'training__C230222__NRS-484B-283-1b__pedestrian'
IDS = ('primary', 'fallback1', 'fallback2', 'fallback3')


def candidate(suffix, ident):
    if suffix not in ('probe_1', 'probe_2') or ident not in IDS:
        raise ValueError('Unknown curb probe or candidate')
    start = .5 if suffix == 'probe_1' else 3.5
    knobs = {'pedestrian_spawn_x_m': -4.5, 'pedestrian_pre_roll_s': 0.0,
             'pedestrian_departure_s': start, 'pedestrian_target_speed_mps': 3.0,
             'pedestrian_control': 'target_velocity', 'vehicle_start_y_m': -18.0,
             'vehicle_target_speed_mps': 4.0,
             'vehicle_control': 'speed_until_observed_departure_then_brake',
             'vehicle_reaction_s': 0.8, 'vehicle_brake_command': 1.0,
             'camera_distance_m': 8.0, 'camera_width': 1280, 'camera_height': 720}
    trigger = {'metric': 'initial', 'source': 'none', 'threshold': None,
               'physical_observation': None}
    if ident == 'fallback1':
        knobs.update(pedestrian_spawn_x_m=-6.5, pedestrian_pre_roll_s=2/3)
        trigger = {'metric': 'native_initial_footprint_clearance_m_below',
                   'source': 'original_native_pedestrian_footprint_and_road_edge',
                   'threshold': 1.25, 'physical_observation': None}
    elif ident == 'fallback2':
        knobs.update(pedestrian_control='bounded_acceleration_to_target_velocity')
        trigger = {'metric': 'native_first_departure_acceleration_mps2_above',
                   'source': 'original_native_pedestrian_velocity_and_frame_times',
                   'threshold': 4.0, 'physical_observation': None}
    elif ident == 'fallback3':
        knobs.update(camera_distance_m=4.0)
        trigger = {'metric': 'original_curb_and_vehicle_visibility_fraction_below',
                   'source': 'independent_original_camera_pixel_audit',
                   'threshold': .95, 'physical_observation': None}
    return {'case_id': BASE + '__' + suffix, 'candidate_id': ident,
            'law_id': 'NRS-484B-283-1b', 'cell_id': 'C230222', 'actor': 'pedestrian',
            'duration_s': 12, 'rate_hz': 20, 'road_source': 'native/road.xodr',
            'comparison_variable': 'pedestrian_departure_s', 'engineering': knobs,
            'trigger': trigger, 'status': 'unselected_cpu_construction_plan_no_native_proof',
            'actual_driver_yield_measured': False, 'impossibility_to_yield_proven': False}


def synthetic_trigger_metrics(folder):
    rows = [json.loads(line) for line in (Path(folder) / 'curb-samples.jsonl').read_text().splitlines()
            if line.strip()]
    front = max(point[0] for point in rows[0]['pedestrian_footprint_xy_m'])
    return {'synthetic_spawn_clearance_m': round(-3.5 - front, 3),
            'physical_spawn_clearance_m': None, 'physical_departure_acceleration_mps2': None,
            'original_pixel_visibility_fraction': None,
            'scope': 'synthetic geometry only; Native trigger events unmeasured'}


def build():
    paths = []
    for suffix in ('probe_1', 'probe_2'):
        plans = [candidate(suffix, ident) for ident in IDS]
        if len({json.dumps(plan['engineering'], sort_keys=True) for plan in plans}) != 4:
            raise ValueError('Curb candidate knobs are not distinct')
        for plan in plans:
            path = HERE / 'draft-candidates' / suffix / plan['candidate_id'] / 'construction.json'
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(plan, indent=2) + '\n')
            paths.append(str(path.relative_to(HERE)))
    summary = {'format': 'c230222-curb-engineering-plans-v1',
               'unselected_candidate_plans': len(paths), 'paths': paths,
               'synthetic_trigger_metrics': synthetic_trigger_metrics(
                   Path(json.loads((HERE / 'curb-summary.json').read_text())['records'][0]['retained_positive'])),
               'physically_measured_triggers': 0, 'selected_cases': 0}
    (HERE / 'curb-engineering-summary.json').write_text(json.dumps(summary, indent=2) + '\n')
    return summary


if __name__ == '__main__':
    print(json.dumps(build()))

"""One requested driver response policy for both curb-entry probes.

This only schedules controls. Native speed, stopping distance and yield are
measured later from retained actor state; CPU checks never claim realization.
"""


class BrakingPolicy:
    def __init__(self, reaction_s=0.8, speed_threshold_mps=0.2):
        if reaction_s <= 0 or speed_threshold_mps <= 0:
            raise ValueError('Driver policy thresholds must be positive')
        self.reaction_s = reaction_s
        self.speed_threshold_mps = speed_threshold_mps
        self.departure_observed_s = None
        self.brake_command_onset_s = None

    def command(self, time_s):
        if time_s < 0:
            raise ValueError('Driver policy time must be nonnegative')
        if self.departure_observed_s is None or time_s + 1e-9 < self.departure_observed_s + self.reaction_s:
            return 'hold_approach_speed'
        if self.brake_command_onset_s is None:
            self.brake_command_onset_s = time_s
        return 'full_brake'

    def observe(self, time_s, pedestrian_speed_mps):
        if time_s < 0 or pedestrian_speed_mps < 0:
            raise ValueError('Driver policy observation invalid')
        if self.departure_observed_s is None and pedestrian_speed_mps > self.speed_threshold_mps:
            self.departure_observed_s = time_s
        return self.departure_observed_s


def cpu_probe(departure_s, rate_hz=20):
    policy = BrakingPolicy()
    states = []
    for frame in range(240):
        time_s = frame/rate_hz
        states.append(policy.command(time_s))
        policy.observe(time_s, 3 if time_s >= departure_s else 0)
    return {'departure_observed_s': policy.departure_observed_s,
            'brake_command_onset_s': policy.brake_command_onset_s,
            'brake_command_count': states.count('full_brake'),
            'policy': 'pedestrian-speed-triggered 0.8 s reaction then full brake',
            'physical_braking_measured': False}

"""Source-bound curb departure and conditional stopping margins; no legal verdict."""
import hashlib
import json
import math
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def point(value, name):
    if not isinstance(value, list) or len(value) != 2 or any(
        type(v) not in (int, float) or not math.isfinite(v) for v in value
    ):
        raise ValueError('Invalid original ' + name)
    return tuple(float(v) for v in value)


def measure(samples_path, context_path):
    samples_path, context_path = Path(samples_path), Path(context_path)
    road = context_path.parent / 'road.xodr'
    for path in (samples_path, context_path, road):
        if not path.is_file():
            raise ValueError('Missing required source: ' + path.name)
    context = json.loads(context_path.read_text())
    if context.get('authored_road_sha256') != sha(road):
        raise ValueError('Curb source road hash differs')
    kind = context.get('source_kind')
    if kind not in ('synthetic_scene_request', 'native_observation'):
        raise ValueError('Curb source provenance missing')
    if context.get('frozen_cell') != {'layout': 'road', 'maneuver': 'travel', 'control': 'curb'}:
        raise ValueError('Frozen curb cell differs')
    if context.get('road_width_m') != 7 or context.get('vehicle_conflict_y_m') != 0:
        raise ValueError('Curb geometry differs')
    edge = point(context.get('curb_edge_xy_m'), 'curb edge')
    direction = point(context.get('pedestrian_crossing_forward_xy'), 'crossing direction')
    if abs(math.hypot(*direction) - 1) > .001:
        raise ValueError('Curb crossing direction invalid')
    reaction = context.get('assumed_driver_reaction_s')
    deceleration = context.get('assumed_deceleration_mps2')
    if reaction != [0.8, 1.2] or deceleration != [3.0, 5.0]:
        raise ValueError('Curb conditional stopping assumptions differ')
    if kind == 'native_observation' and (
        not context.get('native_road_sha256') or not context.get('vehicle_source_audit_sha256')
    ):
        raise ValueError('Native curb road or vehicle provenance missing')
    rows = [json.loads(line) for line in samples_path.read_text().splitlines() if line.strip()]
    if len(rows) != 240:
        raise ValueError('Full 240-frame curb source required')
    previous = None
    entry = None
    vehicle_at_arrival = None
    pedestrian_speed_change = None
    first_brake = None
    stopped_before_conflict = None
    for index, row in enumerate(rows):
        frame, time = row.get('native_frame'), row.get('time_s')
        if type(frame) is not int or type(time) not in (int, float) or not math.isfinite(time):
            raise ValueError('Curb frame/time invalid')
        if previous is not None and (frame != previous['native_frame'] + 1 or abs(time - previous['time_s'] - .05) > .002):
            raise ValueError('Curb frame/time order invalid')
        if row.get('pedestrian_id') != context.get('pedestrian_id') or row.get('vehicle_id') != context.get('vehicle_id'):
            raise ValueError('Curb source actor identity differs')
        pose = point(row.get('pedestrian_xy_m'), 'pedestrian pose')
        vehicle = point(row.get('vehicle_xy_m'), 'vehicle pose')
        body = row.get('pedestrian_footprint_xy_m')
        if not isinstance(body, list) or len(body) != 4:
            raise ValueError('Curb pedestrian footprint missing')
        vertices = [point(v, 'pedestrian footprint') for v in body]
        if len(set(vertices)) != 4 or math.dist(pose, (sum(v[0] for v in vertices)/4,
                                                       sum(v[1] for v in vertices)/4)) > .05:
            raise ValueError('Curb pedestrian pose/footprint differs')
        speed = row.get('vehicle_speed_mps')
        ped_speed = row.get('pedestrian_speed_mps')
        if type(speed) not in (int, float) or type(ped_speed) not in (int, float) or speed < 0 or ped_speed < 0:
            raise ValueError('Curb source speed invalid')
        if kind == 'native_observation':
            if not row.get('original_frame_sha256'):
                raise ValueError('Native curb original frame missing')
            if row.get('vehicle_control_request') not in ('hold_approach_speed', 'full_brake'):
                raise ValueError('Native curb driver control source missing')
            if first_brake is None and row['vehicle_control_request'] == 'full_brake':
                first_brake = (previous, row)
            if (first_brake is not None and stopped_before_conflict is None and
                speed <= .2 and vehicle[1] < context['vehicle_conflict_y_m']):
                stopped_before_conflict = row
        progress = [sum((v[i] - edge[i]) * direction[i] for i in (0, 1)) for v in vertices]
        if entry is None and max(progress) > 0:
            entry = (previous, row)
        if pedestrian_speed_change is None and previous is not None and previous['pedestrian_speed_mps'] == 0 and ped_speed > 0:
            pedestrian_speed_change = (previous, row)
        if vehicle_at_arrival is None and vehicle[1] >= context['vehicle_conflict_y_m']:
            vehicle_at_arrival = row
        previous = row
    if any(x is None for x in (entry, pedestrian_speed_change)) or entry[0] is None:
        raise ValueError('Curb departure, entry or vehicle arrival not bracketed')
    if kind == 'synthetic_scene_request' and vehicle_at_arrival is None:
        raise ValueError('Synthetic curb vehicle arrival not bracketed')
    entry_row = entry[1]
    distance = context['vehicle_conflict_y_m'] - entry_row['vehicle_xy_m'][1]
    v = float(entry_row['vehicle_speed_mps'])
    if distance <= 0 or v <= 0:
        raise ValueError('Vehicle must approach conflict point at curb entry')
    shortest = v*reaction[0] + v*v/(2*deceleration[1])
    longest = v*reaction[1] + v*v/(2*deceleration[0])
    margin = [distance-longest, distance-shortest]
    relation = ('conditional_yield_possible' if margin[0] > 0 else
                'conditional_yield_impossible' if margin[1] < 0 else
                'conditional_yield_indeterminate')
    overlap = None
    if vehicle_at_arrival is not None:
        pedestrian_x = vehicle_at_arrival['pedestrian_xy_m'][0]
        overlap = abs(pedestrian_x - context['vehicle_lane_center_x_m']) <= context['vehicle_body_half_width_m'] + .12
    brake_bracket = None if first_brake is None or first_brake[0] is None else {
        'first_frame': first_brake[1]['native_frame'],
        'time_interval_s': [first_brake[0]['time_s'], first_brake[1]['time_s']]}
    return {'format': 'c230222-curb-source-observation-v1',
            'source_sha256': {path.name: sha(path) for path in (samples_path, context_path, road)},
            'source_kind': kind, 'original_frames': len(rows), 'rate_hz': 20,
            'first_curb_departure': {'first_frame': pedestrian_speed_change[1]['native_frame'],
                                     'time_interval_s': [pedestrian_speed_change[0]['time_s'],
                                                         pedestrian_speed_change[1]['time_s']]},
            'first_roadway_entry': {'first_frame': entry_row['native_frame'],
                                     'time_interval_s': [entry[0]['time_s'], entry_row['time_s']]},
            'vehicle_distance_at_entry_m': distance, 'vehicle_speed_at_entry_mps': v,
            'conditional_stopping_distance_range_m': [shortest, longest],
            'conditional_stopping_margin_range_m': margin,
            'conditional_yield_relation': relation,
            'authored_overlap_at_vehicle_arrival': overlap,
            'source_brake_command': brake_bracket,
            'source_vehicle_stop_before_conflict': (None if kind != 'native_observation'
                                                    else stopped_before_conflict is not None),
            'source_vehicle_stop_frame': (None if stopped_before_conflict is None
                                          else stopped_before_conflict['native_frame']),
            'actual_driver_yield_observed': False, 'driver_capability_measured': False,
            'impossibility_to_yield_proven': False, 'introductory_exceptions_reviewed': False,
            'legal_verdict_claimed': False}
